import fs from 'fs';
import path from 'path';
import { getHistoryStorePath } from './config.js';

export type CommandRecord = {
  command: string;
  timestamp: number;
  durationMs: number;
};

export type HistoryStats = {
  total: number;
  mostUsed: string[];
  averageSessionLength: number;
  recent: CommandRecord[];
};

const MAX_HISTORY = 500;

function readStore(): CommandRecord[] {
  const file = getHistoryStorePath();
  if (!fs.existsSync(file)) return [];
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8')) as CommandRecord[];
  } catch {
    return [];
  }
}

function writeStore(records: CommandRecord[]) {
  const file = getHistoryStorePath();
  fs.writeFileSync(file, JSON.stringify(records.slice(-MAX_HISTORY), null, 2));
}

export function recordCommand(command: string, durationMs: number) {
  const records = readStore();
  records.push({ command, timestamp: Date.now(), durationMs });
  writeStore(records);
}

export function suggestNextCommand(): string | undefined {
  const records = readStore();
  if (records.length < 2) return undefined;
  const last = records[records.length - 1]?.command;
  const combos: Record<string, Record<string, number>> = {};
  for (let i = 1; i < records.length; i++) {
    const prev = records[i - 1].command;
    const curr = records[i].command;
    combos[prev] = combos[prev] || {};
    combos[prev][curr] = (combos[prev][curr] || 0) + 1;
  }
  const nextMap = combos[last] || {};
  const sorted = Object.entries(nextMap).sort((a, b) => b[1] - a[1]);
  return sorted[0]?.[0];
}

export function inlineSuggestion(partial: string): string | undefined {
  const records = readStore();
  const matches = records.map(r => r.command).filter(cmd => cmd.startsWith(partial));
  const counts = matches.reduce<Record<string, number>>((acc, cur) => {
    acc[cur] = (acc[cur] || 0) + 1;
    return acc;
  }, {});
  const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  return sorted[0]?.[0];
}

export function computeStats(): HistoryStats {
  const records = readStore();
  const total = records.length;
  const freq = records.reduce<Record<string, number>>((acc, cur) => {
    acc[cur.command] = (acc[cur.command] || 0) + 1;
    return acc;
  }, {});
  const mostUsed = Object.entries(freq)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([cmd]) => cmd);
  const averageSessionLength = records.reduce((sum, cur) => sum + cur.durationMs, 0) / (records.length || 1);
  const recent = records.slice(-10);
  return { total, mostUsed, averageSessionLength, recent };
}

export function loadHistory() {
  return readStore();
}

export function clearHistory() {
  writeStore([]);
}
